147	            @Size(max = 64) @Pattern(regexp = "\\s*((clerk|steward)\\s*(,\\s*(clerk|steward)\\s*)*)?") String value) {
148	
149	        /** The roles entered, each once, comma separated; null when blank. */
150	        String roles() {
151	            String text = value == null ? "" : value.trim();
152	            return text.isEmpty() ? null
153	                    : String.join(",", Arrays.stream(text.split(",")).map(String::trim).distinct().toList());
154	        }
155	    }
156	
